    // Split the relative path into its components
    String[] relativeComponents = relativePath.split("/");
    // Split the full path into its components
    String[] fullComponents = path.split("/");
    // Iterate over the relative components and update the full components accordingly
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            // If the component is "..", remove the last component from the full path
            if (fullComponents.length > 0) {
                fullComponents = Arrays.copyOf(fullComponents, fullComponents.length - 1);
            }
        } else if (!component.isEmpty()) {
            // If the component is not "..", add it to the full path
            fullComponents = Arrays.copyOf(fullComponents, fullComponents.length + 1);
            fullComponents[fullComponents.length - 1] = component;
        }
    }
    // Join the full components into a single string
    return String.join("/", fullComponents);
